/**
 * Slate Dark: Cloud9 editor theme in the colours of the slate-dark skin, whose
 * default editor theme it is (plugins/c9.ide.theme.slate/plugin.js).
 * See slate-dark.css, generated by tools/gen-themes.js.
 */
define(function(require, exports, module) {

exports.isDark = true;
exports.cssClass = "ace-slate-dark";
exports.cssText = require("text!./slate-dark.css");

var dom = require("ace/lib/dom");
dom.importCssString(exports.cssText, exports.cssClass);
});
